begin; grant workspace_admin_owner,workspace_review_ingest_owner to current_user; insert into public.review_item(id,kind,severity,subject_ref,note,tenant_scope_state,detected_at) select ('13900000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,case when g%2=0 then 'content_drift' else 'fetch_failure' end,case when g%2=0 then 'warning' else 'error' end,'private-'||g,'private-note','platform_only','2026-08-27'::timestamptz+g*interval '1 second' from generate_series(1,100) g; insert into public.review_item(id,kind,severity,subject_ref,note,tenant_scope_state,resolved_at) values('13900000-0000-4000-8000-999999999999','content_drift','warning','resolved-private','resolved-private','platform_only',now());
insert into public.election(id,year,round) values('13900000-0000-4000-8001-000000000001',2097,'breakdown'); insert into public.category(id,name) values('13900000-0000-4000-8002-000000000001','Breakdown category'); insert into public.archive_entry(id,capability,source,source_url,mime,fetched_at,status,source_kind) values('breakdown-fiscal','fixture','fixture','https://example.test/fiscal','text/csv',now(),'ok','fiscalizacion'),('breakdown-official','fixture','fixture','https://example.test/official','text/csv',now(),'ok','official'); set local role workspace_admin_owner; insert into workspace_private.section_scope values('98','997'); reset role;
insert into public.review_item(id,kind,severity,subject_ref,tenant_scope_state,detected_at) values('13900000-0000-4000-8000-000000000201','fetch_failure','error','breakdown-private-201','platform_only','2026-08-26'),('13900000-0000-4000-8000-000000000202','content_drift','warning','breakdown-private-202','section_scoped','2026-08-26'),('13900000-0000-4000-8000-000000000203','mesa_tally_divergence','warning','breakdown-private-203','platform_only','2026-08-26'),('13900000-0000-4000-8000-000000000204','fetch_failure','error','breakdown-private-204','platform_only','2026-08-26'); set local role workspace_review_ingest_owner; insert into workspace_private.review_item_section_scope values('13900000-0000-4000-8000-000000000202','98','997'); reset role;
set local role workspace_review_ingest_owner; update workspace_private.review_item_context set context_role='observed',source_kind='fiscalizacion',archive_availability='available',election_year=2097,election_id='13900000-0000-4000-8001-000000000001',category_id='13900000-0000-4000-8002-000000000001',archive_entry_id='breakdown-fiscal',unknown_reason=null where review_item_id in ('13900000-0000-4000-8000-000000000202','13900000-0000-4000-8000-000000000203'); insert into workspace_private.review_item_context(review_item_id,context_role,source_kind,archive_availability,election_year,election_id,category_id,archive_entry_id) values('13900000-0000-4000-8000-000000000203','comparison','official','available',2097,'13900000-0000-4000-8001-000000000001','13900000-0000-4000-8002-000000000001','breakdown-official'); update workspace_private.review_item_context set context_role='observed',source_kind='official',archive_availability='unknown',election_year=2098,unknown_reason='source_archive_not_attributable' where review_item_id='13900000-0000-4000-8000-000000000204'; reset role; select plan(34);
select ok(to_regprocedure('workspace_api.review_items(integer,integer)') is not null and to_regprocedure('workspace_private.review_item_is_authorized(uuid)') is not null,'tenant review functions remain installed');
select ok(to_regprocedure('workspace_private.platform_review_items(integer,integer)') is not null,'platform review interface exists');
select ok((select bool_and(r.rolname='workspace_query_owner') from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid in ('workspace_api.review_items(integer,integer)'::regprocedure,'workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'tenant review functions retain the query owner');
select ok((select r.rolname='workspace_admin_owner' and p.prosecdef and p.proconfig @> array['search_path=pg_catalog, workspace_private, public, pg_temp'] from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='workspace_private.platform_review_items(integer,integer)'::regprocedure),'platform interface has exact owner and pinned definer context');
select ok(has_function_privilege('workspace_platform_admin','workspace_private.platform_review_items(integer,integer)','EXECUTE') and not has_function_privilege('anon','workspace_private.platform_review_items(integer,integer)','EXECUTE') and not has_function_privilege('authenticated','workspace_private.platform_review_items(integer,integer)','EXECUTE') and (to_regrole('service_role') is null or not has_function_privilege('service_role','workspace_private.platform_review_items(integer,integer)','EXECUTE')),'only platform administration can execute the platform interface');
select ok((select bool_and(not has_table_privilege(role_name,'public.review_item','SELECT') and not has_table_privilege(role_name,'public.review_item_unresolved_count','SELECT') and not exists(select 1 from unnest(array['id','kind','severity','subject_ref','detected_at','resolved_at','note','created_at','tenant_scope_state']) column_name where has_column_privilege(role_name,'public.review_item',column_name,'SELECT')) and not has_column_privilege(role_name,'public.review_item_unresolved_count','unresolved_count','SELECT')) from unnest(array['anon','authenticated','service_role']) role_name where to_regrole(role_name) is not null),'client and service roles have no table or column review SELECT');
select ok((select d like '%tenant_scope_state=''platform_only''%' and d like '%resolved_atisnull%' and d like '%limitp_limitoffsetp_offset%' and d like '%category_counts%' and d like '%reason_counts%' and d like '%pagination_bound%' and d like '%octet_length(payload::text)>8192%' and d not like '%subject_ref%' and d not like '%note%' from (select regexp_replace(lower(pg_get_functiondef('workspace_private.platform_review_items(integer,integer)'::regprocedure)),'\s+','','g') d) f),'platform list is safe, bounded, grouped, and platform-only');
select ok((select d like '%authorized_section_scopes()%' and d like '%frompublic.review_item%' and d like '%resolved_atisnull%' and d like '%limitp_limitoffsetp_offset%' and d like '%octet_length(payload::text)>120000%' and d not like '%subject_ref%' and d not like '%note%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.review_items(integer,integer)'::regprocedure)),'\s+','','g') d) f),'tenant review list remains bounded and scope-authorized');
select ok((select d like '%review_item_section_scope%' and d like '%authorized_section_scopes()%' and d not like '%platform_only%' from (select regexp_replace(lower(pg_get_functiondef('workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'\s+','','g') d) f),'tenant authorization predicate is unchanged');
select ok((select count(*) filter(where policyname in ('workspace_query_owner_review_select','workspace_admin_owner_platform_review_select'))=2 and count(*) filter(where policyname='workspace_query_owner_review_select' and qual like '%review_item_is_authorized%')=1 and count(*) filter(where policyname='workspace_admin_owner_platform_review_select' and qual like '%platform_only%')=1 and count(*) filter(where policyname='review_item_authenticated_read')=0 from pg_policies where schemaname='public' and tablename='review_item'),'tenant direct policy is gone while owner policies are exact');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.review_item_unresolved_count'::regclass),'legacy count view remains security invoker');
select ok((select indisvalid and indisready from pg_index where indexrelid='public.review_item_authorized_unresolved_idx'::regclass),'tenant ordering index remains valid');
select ok((select indisvalid and indisready and lower(pg_get_indexdef(indexrelid)) like '%tenant_scope_state = ''platform_only''::text%' from pg_index where indexrelid='public.review_item_platform_unresolved_idx'::regclass),'platform ordering index is valid and partial');
create temporary table platform_review_payload(label text primary key,payload jsonb) on commit drop; grant insert,select on platform_review_payload to workspace_platform_admin; grant workspace_platform_admin to current_user; set local role workspace_platform_admin; insert into platform_review_payload values('page',workspace_private.platform_review_items(1,0)),('full',workspace_private.platform_review_items(100,0)),('empty',workspace_private.platform_review_items(1,2000000000)),('breakdown',workspace_private.platform_review_breakdown(2,1)),('breakdown-full',workspace_private.platform_review_breakdown(100,0)),('breakdown-empty',workspace_private.platform_review_breakdown(1,2000000000)); reset role;
select is((select payload->>'status' from platform_review_payload where label='page'),'ok','non-empty platform page is ok');
select is((select payload#>>'{items,0,id}' from platform_review_payload where label='page'),'13900000-0000-4000-8000-000000000100','platform page is ordered newest first');
select is((select sum((entry->>'count')::integer) from platform_review_payload cross join lateral jsonb_array_elements(payload->'category_counts') entry where label='page'),103::bigint,'category breakdown covers every unresolved platform row');
select is((select sum((entry->>'count')::integer) from platform_review_payload cross join lateral jsonb_array_elements(payload->'reason_counts') entry where label='page'),103::bigint,'reason breakdown covers every unresolved platform row');
select is((select payload->>'status' from platform_review_payload where label='full'),'payload_too_large','oversized safe projection fails closed');
select is((select payload->>'status' from platform_review_payload where label='empty'),'no_rows','an empty bounded page is distinguished from ok');
select ok((select r.rolname='workspace_review_ingest_owner' and p.prosecdef and p.proconfig @> array['search_path=pg_catalog, workspace_private, public, pg_temp'] from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='workspace_private.platform_review_breakdown(integer,integer)'::regprocedure),'breakdown uses the least-privilege ingest owner and pinned definer context');
select ok(has_function_privilege('workspace_platform_admin','workspace_private.platform_review_breakdown(integer,integer)','EXECUTE') and (select bool_and(not has_function_privilege(role_name,'workspace_private.platform_review_breakdown(integer,integer)','EXECUTE')) from unnest(array['anon','authenticated','service_role','etl_writer','workspace_query_owner','workspace_admin_owner']) role_name where to_regrole(role_name) is not null),'only the owner and platform administration can execute the breakdown');
select is((select payload->>'status' from platform_review_payload where label='breakdown'),'ok','breakdown page succeeds');
select is((select (payload->>'total_items')::bigint from platform_review_payload where label='breakdown'),104::bigint,'total items remain distinct across divergence contexts');
select is((select (payload->>'total_groups')::bigint from platform_review_payload where label='breakdown'),6::bigint,'all safe review groups are counted');
select is((select payload->'groups' from platform_review_payload where label='breakdown'),jsonb_build_array(jsonb_build_object('category','content_drift','reason','warning','tenant_scope_state','section_scoped','context_role','observed','source_kind','fiscalizacion','archive_availability','available','election_year',2097,'election_round','breakdown','category_name','Breakdown category','archive_linked',true,'rows',1),jsonb_build_object('category','fetch_failure','reason','error','tenant_scope_state','platform_only','context_role','observed','source_kind','official','archive_availability','unknown','election_year',2098,'election_round',null,'category_name',null,'archive_linked',false,'rows',1)),'group ordering is exact and null-safe');
select is((select count(*) from platform_review_payload cross join lateral jsonb_array_elements(payload->'groups') g where label='breakdown-full' and g->>'category'='mesa_tally_divergence'),2::bigint,'one divergence item contributes its two safe context groups');
select is((select payload->'exclusions' from platform_review_payload where label='breakdown'),jsonb_build_array(jsonb_build_object('reason','pagination_bound','groups',4),jsonb_build_object('reason','resolved_items','rows',1,'categories',jsonb_build_array(jsonb_build_object('category','content_drift','reason','warning','rows',1)))),'pagination and resolved exclusions are both reported');
select is((select (exclusion->>'rows')::bigint from platform_review_payload cross join lateral jsonb_array_elements(payload->'exclusions') exclusion where label='breakdown-full' and exclusion->>'reason'='resolved_items'),1::bigint,'resolved exclusion reports the distinct resolved item total');
select is((select exclusion->'categories' from platform_review_payload cross join lateral jsonb_array_elements(payload->'exclusions') exclusion where label='breakdown-full' and exclusion->>'reason'='resolved_items'),jsonb_build_array(jsonb_build_object('category','content_drift','reason','warning','rows',1)),'resolved exclusion category and reason breakdown is exact');
select ok((select bool_and(payload::text !~ '"(id|review_item_id|context_id|election_id|category_id|archive_entry_id|subject_ref|note|distrito_code|seccion_code|circuito_code|establecimiento_code|mesa_code|list_id|source_row_index|scope|source)"\s*:') from platform_review_payload where label like 'breakdown%'),'breakdown payloads contain no sensitive keys anywhere');
select throws_ok($$select workspace_private.platform_review_breakdown(0,0)$$,'22023','invalid platform review breakdown pagination','zero limit is rejected');
select throws_ok($$select workspace_private.platform_review_breakdown(1,2000000001)$$,'22023','invalid platform review breakdown pagination','unsafe offset is rejected');
select is((select jsonb_build_object('status',payload->>'status','truncated',payload->'truncated','exclusions',payload->'exclusions') from platform_review_payload where label='breakdown-empty'),jsonb_build_object('status','no_rows','truncated',true,'exclusions',jsonb_build_array(jsonb_build_object('reason','pagination_bound','groups',6),jsonb_build_object('reason','resolved_items','rows',1,'categories',jsonb_build_array(jsonb_build_object('category','content_drift','reason','warning','rows',1))))),'empty pages report unresolved pagination and resolved exclusions');
select throws_ok($$set local role anon; select workspace_private.platform_review_breakdown(1,0)$$,'42501','permission denied for schema workspace_private','anonymous execution is denied');
select * from finish(); rollback;
